exhibit.text:
// main.json  (original ARM template - parameters section)
{
  "parameters": {
    "storageAccountType": {
      "type": "string",
      "defaultValue": "Standard_LRS",
      "allowedValues": ["Standard_LRS", "Standard_GRS", "Standard_ZRS", "Premium_LRS"]
    },
    "Security.Authentication.AAD.Tenant": {
      "type": "string",
      "defaultValue": "00000000-0000-0000-0000-000000000000",
      "metadata": { "description": "AAD tenant ID" }
    }
  }
}

// main.bicep  (result of: az bicep decompile --file main.json)
@allowed([
  'Standard_LRS'
  'Standard_GRS'
  'Standard_ZRS'
  'Premium_LRS'
])
param storageAccountType string = 'Standard_LRS'

@description('AAD tenant ID')
param Security_Authentication_AAD_Tenant string = '00000000-0000-0000-0000-000000000000'

// prod.parameters.json  (values passed at deployment)
{
  "parameters": {
    "storageAccountType": { "value": "Standard_ZRS" },
    "Security.Authentication.AAD.Tenant": { "value": "72f988bf-86f1-41af-91ab-2d7cd011db47" }
  }
}

{
  "parameters": {
    "vmSize": {
      "type": "string",
      "defaultValue": "Standard_D2s_v5",
      "allowedValues": [
        "Standard_D2s_v5",
        "Standard_D4s_v5",
        "Standard_A2_v2"
      ],
      "metadata": {
        "description": "Size of the virtual machine to create."
      }
    }
  }
}

